// Discord bot entry — the token arrives via the environment.
// Use the plugin's Setup tab to store it: kern keeps it in the OS
// credential vault and writes .env, which the host injects at launch.
const token = process.env.{{userOverrides.token_env}};
if (!token) {
  console.error("missing {{userOverrides.token_env}} — save the token in the plugin's Setup tab");
  process.exit(1);
}
console.log("discord bot starting…");
