use serenity::prelude::*;

#[tokio::main]
async fn main() {
    // The token arrives via .env (written by the plugin's Setup tab and
    // injected into this process by the kern host).
    let token = std::env::var("{{userOverrides.token_env}}")
        .expect("missing token — save it in the plugin's Setup tab");
    println!("discord bot starting…");
    // TODO: build and start your serenity client here.
    let _ = token;
}
